<?php
/**
 * Plugin Name: WPBP REST Visible Ability
 * Description: Registers the 'wpbp/rest-visible' ability and exposes it through the Abilities REST API.
 * Version: 1.0.0
 * Requires at least: 6.9
 * Requires PHP: 7.4
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Register the ability category.
 */
function wpbp_register_rest_abilities_category() {
	if ( ! function_exists( 'wp_register_ability_category' ) ) {
		return;
	}

	wp_register_ability_category(
		'wpbp-rest-abilities',
		array(
			'label'       => __( 'WPBP REST Abilities', 'wpbp' ),
			'description' => __( 'Abilities provided by WPBP that are exposed through the Abilities REST API.', 'wpbp' ),
		)
	);
}
add_action( 'wp_abilities_api_categories_init', 'wpbp_register_rest_abilities_category' );

/**
 * Register the REST-visible ability.
 */
function wpbp_register_rest_visible_ability() {
	if ( ! function_exists( 'wp_register_ability' ) ) {
		return;
	}

	wp_register_ability(
		'wpbp/rest-visible',
		array(
			'label'               => __( 'REST Visible Ability', 'wpbp' ),
			'description'         => __( 'Returns basic site information. This ability is available through the Abilities REST API.', 'wpbp' ),
			'category'            => 'wpbp-rest-abilities',
			'input_schema'        => array(
				'type'                 => 'object',
				'properties'           => array(),
				'additionalProperties' => false,
			),
			'output_schema'       => array(
				'type'       => 'object',
				'properties' => array(
					'name' => array(
						'type'        => 'string',
						'description' => __( 'The site title.', 'wpbp' ),
					),
					'url'  => array(
						'type'        => 'string',
						'format'      => 'uri',
						'description' => __( 'The site URL.', 'wpbp' ),
					),
				),
				'required'   => array( 'name', 'url' ),
			),
			'execute_callback'    => 'wpbp_rest_visible_ability_execute',
			'permission_callback' => 'wpbp_rest_visible_ability_permission',
			'meta'                => array(
				'show_in_rest' => true,
				'annotations'  => array(
					'readonly'    => true,
					'destructive' => false,
					'idempotent'  => true,
				),
			),
		)
	);
}
add_action( 'wp_abilities_api_init', 'wpbp_register_rest_visible_ability' );

/**
 * Execute callback for the 'wpbp/rest-visible' ability.
 *
 * @param mixed $input Ability input (unused).
 * @return array
 */
function wpbp_rest_visible_ability_execute( $input = null ) {
	return array(
		'name' => (string) get_bloginfo( 'name' ),
		'url'  => (string) home_url( '/' ),
	);
}

/**
 * Permission callback for the 'wpbp/rest-visible' ability.
 *
 * @param mixed $input Ability input (unused).
 * @return bool
 */
function wpbp_rest_visible_ability_permission( $input = null ) {
	return current_user_can( 'read' );
}
