<?php
/**
 * Register the 'wpbp/greet' ability.
 */
add_action( 'wp_abilities_api_init', 'wpbp_register_greet_ability' );

function wpbp_register_greet_ability() {
	if ( ! function_exists( 'wp_register_ability' ) ) {
		return;
	}

	wp_register_ability(
		'wpbp/greet',
		array(
			'label'               => __( 'Greet', 'wpbp' ),
			'description'         => __( 'Returns a greeting for the provided name.', 'wpbp' ),
			'category'            => 'wpbp-greetings',
			'input_schema'        => array(
				'type'        => 'string',
				'description' => __( 'The name to greet.', 'wpbp' ),
				'default'     => 'world',
			),
			'output_schema'       => array(
				'type'        => 'string',
				'description' => __( 'The greeting message.', 'wpbp' ),
			),
			'execute_callback'    => 'wpbp_execute_greet_ability',
			'permission_callback' => '__return_true',
			'meta'                => array(
				'annotations' => array(
					'readonly'    => true,
					'destructive' => false,
					'idempotent'  => true,
				),
			),
		)
	);
}

/**
 * Execute callback for the 'wpbp/greet' ability.
 *
 * @param string|null $input The name to greet.
 * @return string The greeting.
 */
function wpbp_execute_greet_ability( $input = 'world' ) {
	if ( null === $input || '' === $input ) {
		$input = 'world';
	}

	return 'hello ' . $input;
}
