function wpbp_caching_002( array $values, array $keys, string $group ): array {
	if ( ! empty( $values ) ) {
		wp_cache_set_multiple( $values, $group );
	}

	$result = array();

	if ( empty( $keys ) ) {
		return $result;
	}

	$normalized_keys = array();
	foreach ( $keys as $key ) {
		if ( is_int( $key ) || is_string( $key ) ) {
			$normalized_keys[] = $key;
		}
	}

	if ( empty( $normalized_keys ) ) {
		return $result;
	}

	$cached = wp_cache_get_multiple( $normalized_keys, $group );

	if ( ! is_array( $cached ) ) {
		$cached = array();
	}

	foreach ( $normalized_keys as $key ) {
		// Use array_key_exists so cached false, 0, '', null, etc. are preserved as-is.
		if ( array_key_exists( $key, $cached ) ) {
			$result[ $key ] = $cached[ $key ];
		} else {
			$result[ $key ] = false;
		}
	}

	return $result;
}
