	wp_cache_set_multiple_salted( $values, $group, $salt );

	$stale_salt   = $salt;
	$stale_salt[] = 'stale';

	$current_values = wp_cache_get_multiple_salted( $keys, $group, $salt );
	$stale_values   = wp_cache_get_multiple_salted( $keys, $group, $stale_salt );

	$current = array();
	$stale   = array();

	foreach ( $keys as $key ) {
		$current[ $key ] = array_key_exists( $key, $current_values )
			? $current_values[ $key ]
			: false;
		$stale[ $key ] = array_key_exists( $key, $stale_values )
			? $stale_values[ $key ]
			: false;
	}

	return array(
		'current' => $current,
		'stale'   => $stale,
	);
}
