<?php
/**
 * Retrieve user IDs whose user meta for the given key exactly matches the given value.
 *
 * @param string $meta_key   The user meta key to match.
 * @param string $meta_value The exact meta value to match.
 * @return int[] Array of matching user IDs.
 */
function wpbp_comments_users_002( string $meta_key, string $meta_value ): array {
	$meta_key = sanitize_key( $meta_key );

	if ( '' === $meta_key ) {
		return array();
	}

	$query = new WP_User_Query(
		array(
			'fields'      => 'ID',
			'number'      => -1,
			'count_total' => false,
			'meta_query'  => array(
				array(
					'key'     => $meta_key,
					'value'   => $meta_value,
					'compare' => '=',
					'type'    => 'CHAR',
				),
			),
		)
	);

	$results = $query->get_results();

	if ( empty( $results ) || ! is_array( $results ) ) {
		return array();
	}

	return array_values( array_unique( array_map( 'intval', $results ) ) );
}
