<?php
/**
 * Registers the WPBP Support Desk connector with the WordPress Connectors API.
 *
 * @package WPBP_SupportDesk
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Registers the 'wpbp_supportdesk' connector.
 *
 * @param WP_Connector_Registry $registry The connector registry instance.
 */
function wpbp_supportdesk_register_connector( $registry ) {
	if ( ! $registry instanceof WP_Connector_Registry ) {
		return;
	}

	if ( method_exists( $registry, 'is_registered' ) && $registry->is_registered( 'wpbp_supportdesk' ) ) {
		return;
	}

	$registry->register(
		'wpbp_supportdesk',
		array(
			'name'           => __( 'WPBP Support Desk', 'wpbp-supportdesk' ),
			'description'    => __( 'Connects WordPress to the WPBP Support Desk for managing customer support tickets.', 'wpbp-supportdesk' ),
			'type'           => 'support_desk',
			'authentication' => array(
				'method' => 'none',
			),
			'plugin'         => array(
				'file' => 'wpbp-supportdesk/wpbp-supportdesk.php',
			),
		)
	);
}
add_action( 'wp_connectors_init', 'wpbp_supportdesk_register_connector' );
