<?php
/**
 * Delete exactly the row matching the supplied lookup key from the
 * WordPress-prefixed `wpbp_database_005` custom table.
 *
 * @param string $lookup_key The lookup key identifying the row to delete.
 * @return int|false Number of affected rows, or false on error.
 */
function wpbp_database_005( string $lookup_key ): int|false {
	global $wpdb;

	if ( '' === $lookup_key ) {
		return false;
	}

	$table = $wpdb->prefix . 'wpbp_database_005';

	// Table name is built from the trusted WordPress prefix and a fixed suffix;
	// the user-supplied value is bound through $wpdb->prepare().
	$sql = $wpdb->prepare(
		"DELETE FROM `{$table}` WHERE `lookup_key` = %s LIMIT 1",
		$lookup_key
	);

	$result = $wpdb->query( $sql );

	if ( false === $result ) {
		return false;
	}

	return (int) $result;
}
