<?php
function wpbp_gb_block_api_002(): bool {
	if ( ! function_exists( 'register_block_type' ) || ! class_exists( 'WP_Block_Type_Registry' ) ) {
		return false;
	}

	$registry = WP_Block_Type_Registry::get_instance();

	if ( $registry->is_registered( 'wpbp/auto' ) ) {
		return true;
	}

	$block = register_block_type(
		'wpbp/auto',
		array(
			'api_version'     => 3,
			'title'           => 'Auto Message',
			'category'        => 'widgets',
			'attributes'      => array(
				'message' => array(
					'type'    => 'string',
					'default' => 'Hi',
				),
			),
			'supports'        => array(
				'autoRegister' => true,
			),
			'render_callback' => static function ( $attributes ) {
				$message = isset( $attributes['message'] ) && is_string( $attributes['message'] )
					? $attributes['message']
					: 'Hi';

				$wrapper_attributes = function_exists( 'get_block_wrapper_attributes' )
					? get_block_wrapper_attributes()
					: '';

				return sprintf(
					'<div %1$s>%2$s</div>',
					$wrapper_attributes,
					esc_html( $message )
				);
			},
		)
	);

	return $block instanceof WP_Block_Type && $registry->is_registered( 'wpbp/auto' );
}
