```php
<?php

function wpbp_gb_block_editor_004(): bool
{
    if ( ! function_exists( 'register_block_type' ) ) {
        return false;
    }

    $block_type = register_block_type(
        'wpbp/text-indent',
        array(
            'api_version'     => 3,
            'title'           => 'Text Indent',
            'category'        => 'text',
            'attributes'      => array(
                'content' => array(
                    'type'    => 'string',
                    'default' => '',
                ),
            ),
            'supports'        => array(
                'typography' => array(
                    'textIndent' => true,
                ),
            ),
            'render_callback' => static function ( $attributes, $content = '', $block = null ) {
                $text = '';

                if ( isset( $attributes['content'] ) && is_string( $attributes['content'] ) ) {
                    $text = $attributes['content'];
                }

                $wrapper_attributes = function_exists( 'get_block_wrapper_attributes' )
                    ? get_block_wrapper_attributes()
                    : 'class="wp-block-wpbp-text-indent"';

                return sprintf(
                    '<p %1$s>%2$s</p>',
                    $wrapper_attributes,
                    wp_kses_post( $text )
                );
            },
        )
    );

    return $block_type instanceof WP_Block_Type;
}
