<?php

function wpbp_gb_block_hooks_001(): bool
{
    if (!function_exists('register_block_type') || !class_exists('WP_Block_Type_Registry')) {
        return false;
    }

    $block_name = 'wpbp/cta-hook';
    $registry   = WP_Block_Type_Registry::get_instance();

    if ($registry->is_registered($block_name)) {
        return true;
    }

    $result = register_block_type(
        $block_name,
        array(
            'api_version'     => 3,
            'title'           => 'CTA Hook',
            'category'        => 'widgets',
            'block_hooks'     => array(
                'core/paragraph' => 'after',
            ),
            'supports'        => array(
                'html' => false,
            ),
            'render_callback' => static function ($attributes = array(), $content = '', $block = null): string {
                return '<p>CTA</p>';
            },
        )
    );

    return ($result instanceof WP_Block_Type) && $registry->is_registered($block_name);
}
