<?php
function wpbp_gb_block_hooks_004(): bool {
	if ( ! function_exists( 'register_block_type' ) ) {
		return false;
	}

	$registry = WP_Block_Type_Registry::get_instance();
	if ( $registry->is_registered( 'wpbp/single-hook' ) ) {
		return true;
	}

	$block = register_block_type(
		'wpbp/single-hook',
		array(
			'api_version'     => 3,
			'title'           => 'Single Hook',
			'category'        => 'widgets',
			'block_hooks'     => array(
				'core/paragraph' => 'after',
			),
			'supports'        => array(
				'multiple' => false,
			),
			'render_callback' => static function ( $attributes = array(), $content = '', $block = null ) {
				return '<p>Once</p>';
			},
		)
	);

	return $block instanceof WP_Block_Type;
}
