<?php

function wpbp_gb_markup_003(): string
{
    $items = array( 'Alpha', 'Beta', 'Gamma' );

    $inner = array();
    foreach ( $items as $item ) {
        $inner[] = "<!-- wp:list-item -->\n<li>" . $item . "</li>\n<!-- /wp:list-item -->";
    }

    return "<!-- wp:list -->\n"
        . '<ul class="wp-block-list">'
        . implode( "\n\n", $inner )
        . "</ul>\n"
        . '<!-- /wp:list -->';
}
