<?php
/**
 * Registers the "WPBP Fonts" Font Library collection containing the inline "Bench Sans" family.
 *
 * @return bool True if the collection is registered (or already was), false otherwise.
 */
function wpbp_gb_font_library_002(): bool {
	if ( ! function_exists( 'wp_register_font_collection' ) ) {
		return false;
	}

	$slug = 'wpbp-fonts';

	// Avoid double registration, which would trigger a _doing_it_wrong notice.
	if ( class_exists( 'WP_Font_Library' ) && method_exists( 'WP_Font_Library', 'get_instance' ) ) {
		$library = WP_Font_Library::get_instance();
		if ( method_exists( $library, 'get_font_collection' ) ) {
			$existing = $library->get_font_collection( $slug );
			if ( $existing instanceof WP_Font_Collection ) {
				return true;
			}
		}
	}

	$args = array(
		'name'          => 'WPBP Fonts',
		'description'   => 'Fonts provided by WPBP.',
		'font_families' => array(
			array(
				'font_family_settings' => array(
					'name'       => 'Bench Sans',
					'slug'       => 'bench-sans',
					'fontFamily' => '"Bench Sans", sans-serif',
					'fontFace'   => array(
						array(
							'fontFamily' => 'Bench Sans',
							'fontStyle'  => 'normal',
							'fontWeight' => '400',
							'src'        => 'https://example.com/fonts/bench-sans-regular.woff2',
						),
					),
				),
				'categories'           => array( 'sans-serif' ),
			),
		),
		'categories'    => array(
			array(
				'name' => 'Sans Serif',
				'slug' => 'sans-serif',
			),
		),
	);

	$result = wp_register_font_collection( $slug, $args );

	if ( is_wp_error( $result ) ) {
		return false;
	}

	return $result instanceof WP_Font_Collection;
}
