<?php

if ( ! function_exists( 'wpbp_gb_interactivity_api_002' ) ) {
	/**
	 * Returns a safe Interactivity API context attribute for the 'wpbp/store' namespace.
	 *
	 * @param array $context Context data.
	 * @return string Complete data-wp-context attribute string.
	 */
	function wpbp_gb_interactivity_api_002( array $context ): string {
		$namespace = 'wpbp/store';

		if ( function_exists( 'wp_interactivity_data_wp_context' ) ) {
			return wp_interactivity_data_wp_context( $context, $namespace );
		}

		$json = wp_json_encode(
			empty( $context ) ? new stdClass() : $context,
			JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP
		);

		if ( false === $json ) {
			$json = '{}';
		}

		return "data-wp-context='" . $namespace . '::' . $json . "'";
	}
}
