				'%3$s' .
			'</button>' .
		'</div>',
		esc_attr( $namespace ),
		esc_attr( $context ),
		esc_html__( 'Toggle', 'wpbp' )
	);

	if ( function_exists( 'wp_interactivity_process_directives' ) ) {
