	$hook_name = 'wpbp_remove_filter';
	$priority  = 0;

	$before = has_filter( $hook_name, $callback );

	if ( false === $before ) {
		return false;
	}

	$removed = remove_filter( $hook_name, $callback, $priority );

	if ( true !== $removed ) {
		return false;
	}

	$after = has_filter( $hook_name, $callback );

	return false === $after;
}
