<?php
/**
 * Return post content after WordPress applies media tag optimizations
 * (srcset/sizes, loading, decoding, fetchpriority, width/height, etc.).
 *
 * @param string      $html    The HTML content to filter.
 * @param string|null $context Optional context for the filter (e.g. 'the_content').
 *                             Defaults to the current filter when null.
 * @return string The filtered HTML.
 */
function wpbp_media_002( string $html, ?string $context = null ): string {
	if ( '' === $html ) {
		return $html;
	}

	// WordPress 5.5+: unified media tag filtering.
	if ( function_exists( 'wp_filter_content_tags' ) ) {
		$filtered = wp_filter_content_tags( $html, $context );
		return is_string( $filtered ) ? $filtered : $html;
	}

	// Fallback for older WordPress versions.
	if ( function_exists( 'wp_make_content_images_responsive' ) ) {
		$filtered = wp_make_content_images_responsive( $html );
		return is_string( $filtered ) ? $filtered : $html;
	}

	return $html;
}
