<?php
/**
 * Return WordPress's extension and MIME type result for an upload filename.
 *
 * Uses wp_check_filetype(), which determines the type solely from the
 * filename's extension and never inspects file contents.
 *
 * @param string     $filename Upload filename (may include a path).
 * @param array|null $mimes    Optional MIME map (extension regex => MIME type).
 *                             Defaults to the allowed MIME types for the site.
 * @return array {
 *     @type string|false $ext  File extension, or false if not matched.
 *     @type string|false $type MIME type, or false if not matched.
 * }
 */
function wpbp_media_005( string $filename, ?array $mimes = null ): array {
	$filename = wp_basename( $filename );

	if ( '' === $filename ) {
		return array(
			'ext'  => false,
			'type' => false,
		);
	}

	$result = wp_check_filetype( $filename, $mimes );

	return array(
		'ext'  => isset( $result['ext'] ) ? $result['ext'] : false,
		'type' => isset( $result['type'] ) ? $result['type'] : false,
	);
}
