function wpbp_post_meta_003( int $post_id, string $meta_key, string $value ): bool {
	if ( $post_id <= 0 || $meta_key === '' ) {
		return false;
	}

	if ( $value !== '' ) {
		return delete_post_meta( $post_id, $meta_key, $value );
	}

	// An empty value makes delete_post_meta() delete every value for this key.
	// Find matching entry IDs, then delete them through the metadata API.
	global $wpdb;

	$meta_ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT meta_id FROM {$wpdb->postmeta}
			 WHERE post_id = %d AND meta_key = %s AND meta_value = %s",
			$post_id,
			$meta_key,
			$value
		)
	);

	$deleted = false;

	foreach ( $meta_ids as $meta_id ) {
		if ( delete_metadata_by_mid( 'post', (int) $meta_id ) ) {
			$deleted = true;
		}
	}

	return $deleted;
}
