	$taxonomy       = 'wpbp_tax_005';
	$registered_now = false;
	$created_term   = false;
	$term_id        = 0;
	$result         = array(
		'slug'     => '',
		'taxonomy' => $taxonomy,
	);

	$name = trim( $name );
	if ( '' === $name ) {
		return $result;
	}

	if ( ! taxonomy_exists( $taxonomy ) ) {
		$registered = register_taxonomy(
			$taxonomy,
			array(),
			array(
				'public'            => false,
				'show_ui'           => false,
				'show_in_rest'      => false,
				'hierarchical'      => false,
				'rewrite'           => false,
				'query_var'         => false,
				'show_admin_column' => false,
			)
		);

		if ( is_wp_error( $registered ) ) {
			return $result;
		}

		$registered_now = true;
	}

	try {
		$inserted = wp_insert_term( $name, $taxonomy );

		if ( is_wp_error( $inserted ) ) {
			$existing_id = $inserted->get_error_data( 'term_exists' );
			if ( $existing_id ) {
				$term_id = (int) $existing_id;
			} else {
				$existing = term_exists( $name, $taxonomy );
				if ( is_array( $existing ) && isset( $existing['term_id'] ) ) {
					$term_id = (int) $existing['term_id'];
				} elseif ( $existing ) {
					$term_id = (int) $existing;
				}
			}
		} elseif ( is_array( $inserted ) && isset( $inserted['term_id'] ) ) {
			$term_id      = (int) $inserted['term_id'];
			$created_term = true;
		}

		if ( $term_id > 0 ) {
			$term = get_term( $term_id, $taxonomy );
			if ( $term instanceof WP_Term ) {
				$result['slug']     = (string) $term->slug;
				$result['taxonomy'] = (string) $term->taxonomy;
			}
		}
	} finally {
		if ( $registered_now ) {
			if ( $created_term && $term_id > 0 ) {
				wp_delete_term( $term_id, $taxonomy );
			}
			unregister_taxonomy( $taxonomy );
		}
	}

	return $result;
}
