<?php
/**
 * Registers a temporary public custom post type with an archive, reads its
 * post type archive link, then unregisters the type if it was created here.
 *
 * @return string The archive URL, or an empty string on failure.
 */
function wpbp_post_types_taxonomy_007(): string
{
    if (
        ! function_exists('register_post_type')
        || ! function_exists('get_post_type_archive_link')
        || ! function_exists('post_type_exists')
    ) {
        return '';
    }

    $post_type        = 'wpbp_cpt_007'; // Must be 20 characters or fewer.
    $registered_here  = false;

    if (! post_type_exists($post_type)) {
        $result = register_post_type(
            $post_type,
            array(
                'label'              => 'WPBP Items 007',
                'labels'             => array(
                    'name'          => 'WPBP Items 007',
                    'singular_name' => 'WPBP Item 007',
                ),
                'public'             => true,
                'publicly_queryable' => true,
                'show_ui'            => false,
                'show_in_menu'       => false,
                'show_in_rest'       => false,
                'has_archive'        => true,
                'rewrite'            => array(
                    'slug'       => 'wpbp-items-007',
                    'with_front' => false,
                ),
                'query_var'          => true,
                'supports'           => array('title'),
            )
        );

        if (is_wp_error($result)) {
            return '';
        }

        $registered_here = true;
    }

    $link = get_post_type_archive_link($post_type);

    if ($registered_here && function_exists('unregister_post_type')) {
        unregister_post_type($post_type);
    }

    if (! is_string($link) || '' === $link) {
        return '';
    }

    return function_exists('esc_url_raw') ? esc_url_raw($link) : $link;
}
