<?php
/**
 * Registers a taxonomy with a custom REST base, verifies the registration,
 * cleans up the registered taxonomy, and returns the REST base that was used.
 *
 * @return string The REST base assigned to the taxonomy, or an empty string on failure.
 */
function wpbp_post_types_taxonomy_008(): string
{
    if (!function_exists('register_taxonomy') || !function_exists('get_taxonomy')) {
        return '';
    }

    $taxonomy  = 'wpbp_tax_008';
    $rest_base = 'wpbp-custom-terms';

    // Remember if the taxonomy already existed so we don't remove something we didn't create.
    $already_registered = function_exists('taxonomy_exists') && taxonomy_exists($taxonomy);

    $labels = array(
        'name'          => 'WPBP Terms',
        'singular_name' => 'WPBP Term',
        'menu_name'     => 'WPBP Terms',
        'all_items'     => 'All WPBP Terms',
        'edit_item'     => 'Edit WPBP Term',
        'add_new_item'  => 'Add New WPBP Term',
        'search_items'  => 'Search WPBP Terms',
    );

    $args = array(
        'labels'                => $labels,
        'public'                => true,
        'hierarchical'          => false,
        'show_ui'               => true,
        'show_admin_column'     => true,
        'show_in_rest'          => true,
        'rest_base'             => $rest_base,
        'rest_namespace'        => 'wp/v2',
        'rest_controller_class' => 'WP_REST_Terms_Controller',
        'query_var'             => true,
        'rewrite'               => false,
    );

    $result = register_taxonomy($taxonomy, array('post'), $args);

    if (function_exists('is_wp_error') && is_wp_error($result)) {
        return '';
    }

    $registered_base = '';
    $tax_object      = get_taxonomy($taxonomy);

    if ($tax_object && isset($tax_object->rest_base)) {
        $registered_base = is_string($tax_object->rest_base) && $tax_object->rest_base !== ''
            ? $tax_object->rest_base
            : $taxonomy;
    }

    // Clean up the taxonomy we registered.
    if (!$already_registered && function_exists('unregister_taxonomy')) {
        unregister_taxonomy($taxonomy);
    }

    return (string) $registered_base;
}
