<?php
/**
 * Return only post IDs matching a search query.
 *
 * @param string $search_term The search term.
 * @return int[] Array of post IDs.
 */
function wpbp_queries_003( string $search_term ): array {
	$search_term = sanitize_text_field( $search_term );

	if ( '' === trim( $search_term ) ) {
		return array();
	}

	$query = new WP_Query(
		array(
			's'                      => $search_term,
			'post_type'              => 'post',
			'post_status'            => 'publish',
			'fields'                 => 'ids',
			'posts_per_page'         => 100,
			'orderby'                => array(
				'date' => 'DESC',
				'ID'   => 'DESC',
			),
			'no_found_rows'          => true,
			'ignore_sticky_posts'    => true,
			'update_post_meta_cache' => false,
			'update_post_term_cache' => false,
			'suppress_filters'       => false,
		)
	);

	return array_map( 'intval', $query->posts );
}
