<?php
function wpbp_queries_004( string $category_slug, array $tag_slugs ): WP_Query {
	$category_slug = sanitize_title( $category_slug );
	$tag_slugs     = array_values(
		array_filter(
			array_map( 'sanitize_title', array_map( 'strval', $tag_slugs ) ),
			'strlen'
		)
	);

	if ( '' === $category_slug || empty( $tag_slugs ) ) {
		return new WP_Query(
			array(
				'post__in'            => array( 0 ),
				'post_type'           => 'post',
				'post_status'         => 'publish',
				'no_found_rows'       => true,
				'ignore_sticky_posts' => true,
			)
		);
	}

	$args = array(
		'post_type'           => 'post',
		'post_status'         => 'publish',
		'ignore_sticky_posts' => true,
		'tax_query'           => array(
			'relation' => 'AND',
			array(
				'taxonomy' => 'category',
				'field'    => 'slug',
				'terms'    => array( $category_slug ),
				'operator' => 'IN',
			),
			array(
				'taxonomy' => 'post_tag',
				'field'    => 'slug',
				'terms'    => $tag_slugs,
				'operator' => 'IN',
			),
		),
	);

	return new WP_Query( $args );
}
