<?php
/**
 * Retrieve approved comments for a given post using WP_Comment_Query.
 *
 * @param int $post_id The post ID.
 * @return array List of approved comments as associative arrays.
 */
function wpbp_queries_007( int $post_id ): array {
	if ( $post_id <= 0 ) {
		return array();
	}

	$query = new WP_Comment_Query(
		array(
			'post_id'       => $post_id,
			'status'        => 'approve',
			'type'          => 'comment',
			'orderby'       => array(
				'comment_date_gmt' => 'ASC',
				'comment_ID'       => 'ASC',
			),
			'order'         => 'ASC',
			'no_found_rows' => true,
			'hierarchical'  => false,
		)
	);

	$comments = $query->get_comments();

	if ( empty( $comments ) || ! is_array( $comments ) ) {
		return array();
	}

	$results = array();

	foreach ( $comments as $comment ) {
		if ( ! $comment instanceof WP_Comment ) {
			continue;
		}

		$results[] = array(
			'id'           => (int) $comment->comment_ID,
			'post_id'      => (int) $comment->comment_post_ID,
			'parent'       => (int) $comment->comment_parent,
			'author'       => (string) $comment->comment_author,
			'author_email' => (string) $comment->comment_author_email,
			'author_url'   => (string) $comment->comment_author_url,
			'user_id'      => (int) $comment->user_id,
			'date'         => (string) $comment->comment_date,
			'date_gmt'     => (string) $comment->comment_date_gmt,
			'content'      => (string) $comment->comment_content,
			'type'         => (string) $comment->comment_type,
			'approved'     => (string) $comment->comment_approved,
		);
	}

	return $results;
}
