<?php
/**
 * Query terms for a supplied taxonomy with hide_empty disabled.
 *
 * @param string $taxonomy Taxonomy slug.
 * @return array List of WP_Term objects (empty array on failure).
 */
function wpbp_queries_008( string $taxonomy ): array {
	$taxonomy = sanitize_key( $taxonomy );

	if ( '' === $taxonomy || ! taxonomy_exists( $taxonomy ) ) {
		return array();
	}

	$query = new WP_Term_Query(
		array(
			'taxonomy'               => $taxonomy,
			'hide_empty'             => false,
			'orderby'                => 'term_id',
			'order'                  => 'ASC',
			'fields'                 => 'all',
			'update_term_meta_cache' => false,
		)
	);

	$terms = $query->get_terms();

	if ( is_wp_error( $terms ) || ! is_array( $terms ) ) {
		return array();
	}

	return array_values( $terms );
}
