<?php
/**
 * Plugin Name: WPBP Status Endpoint
 * Description: Registers a public REST endpoint at /wp-json/wpbp/v1/status.
 * Version:     1.0.0
 * Requires at least: 5.5
 * Requires PHP: 7.0
 * License:     GPL-2.0-or-later
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Register the wpbp/v1/status REST route.
 *
 * @return void
 */
function wpbp_register_status_route() {
	register_rest_route(
		'wpbp/v1',
		'/status',
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => 'wpbp_status_callback',
			'permission_callback' => '__return_true',
		)
	);
}
add_action( 'rest_api_init', 'wpbp_register_status_route' );

/**
 * Handle requests to the status endpoint.
 *
 * @param WP_REST_Request $request The REST request object.
 * @return WP_REST_Response
 */
function wpbp_status_callback( WP_REST_Request $request ) {
	return rest_ensure_response(
		array(
			'status'    => 'ok',
			'timestamp' => (int) time(),
		)
	);
}
