<?php
/**
 * Plugin Name: WPBP Books REST Endpoint
 * Description: Registers /wp-json/wpbp/v1/books/<id> with REST argument validation.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

add_action( 'rest_api_init', 'wpbp_register_books_route' );

function wpbp_register_books_route() {
	register_rest_route(
		'wpbp/v1',
		'/books/(?P<id>[^/]+)',
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => 'wpbp_get_book',
			'permission_callback' => '__return_true',
			'args'                => array(
				'id' => array(
					'description'       => 'Numeric book ID.',
					'type'              => 'string',
					'required'          => true,
					'validate_callback' => 'wpbp_validate_book_id',
					'sanitize_callback' => 'wpbp_sanitize_book_id',
				),
			),
		)
	);
}

function wpbp_validate_book_id( $value, $request, $param ) {
	if ( is_int( $value ) && $value >= 0 ) {
		return true;
	}

	if ( is_string( $value ) && 1 === preg_match( '/^\d+$/', $value ) ) {
		return true;
	}

	return new WP_Error(
		'rest_invalid_param',
		sprintf( '%s must be a numeric ID.', $param ),
		array( 'status' => 400 )
	);
}

function wpbp_sanitize_book_id( $value, $request, $param ) {
	return absint( $value );
}

function wpbp_get_book( WP_REST_Request $request ) {
	$id = (int) $request->get_param( 'id' );

	return rest_ensure_response(
		array(
			'id' => $id,
		)
	);
}
