/**
 * Plugin Name: WPBP Private REST Endpoint
 * Description: Registers a private REST endpoint at /wp-json/wpbp/v1/private that requires the manage_options capability.
 * Version:     1.0.0
 * Author:      WPBP
 * License:     GPL-2.0-or-later
