 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Register the private REST route.
 *
 * @return void
 */
function wpbp_register_private_route() {
	register_rest_route(
		'wpbp/v1',
		'/private',
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => 'wpbp_private_route_callback',
			'permission_callback' => 'wpbp_private_route_permission',
		)
	);
}
add_action( 'rest_api_init', 'wpbp_register_private_route' );

/**
 * Permission callback for the private route.
 *
 * @param WP_REST_Request $request The current request.
 * @return true|WP_Error True if the user can manage options, WP_Error otherwise.
 */
function wpbp_private_route_permission( WP_REST_Request $request ) {
	if ( current_user_can( 'manage_options' ) ) {
		return true;
	}

	return new WP_Error(
		'rest_forbidden',
		esc_html__( 'You do not have permission to access this resource.', 'wpbp' ),
		array( 'status' => rest_authorization_required_code() )
	);
}

/**
 * Callback for the private route.
 *
 * @param WP_REST_Request $request The current request.
 * @return WP_REST_Response The response containing secret data.
 */
function wpbp_private_route_callback( WP_REST_Request $request ) {
	return rest_ensure_response(
		array(
			'secret' => true,
		)
	);
}
