<?php
/**
 * Adds a custom link relation to a WP_REST_Response and returns its links.
 *
 * @param string $url The URL to link to.
 * @return array The links registered on the response.
 */
function wpbp_rest_api_012( string $url ): array {
	$response = new WP_REST_Response();

	$response->add_link(
		'https://api.w.org/custom',
		esc_url_raw( $url ),
		array(
			'embeddable' => true,
		)
	);

	return $response->get_links();
}
