/**
 * Registers a top-priority rewrite rule mapping wpbp-rule/<code> to the wpbp_rule query var.
 *
 * Intended to run on the 'init' hook. Rewrite rules are NOT flushed here;
 * flushing should only occur on plugin activation/deactivation.
 */
function wpbp_rewrite_permalinks_002(): void
{
    // Register the query variable so WordPress recognizes it.
    add_rewrite_tag('%wpbp_rule%', '([^/]+)');

    // Register the rewrite rule at top priority.
    add_rewrite_rule(
        '^wpbp-rule/([^/]+)/?$',
        'index.php?wpbp_rule=$matches[1]',
        'top'
    );
}

add_action('init', 'wpbp_rewrite_permalinks_002');

/**
 * Ensure the query var is public, in case the rewrite tag is registered elsewhere.
 */
add_filter('query_vars', static function (array $vars): array {
    if (!in_array('wpbp_rule', $vars, true)) {
        $vars[] = 'wpbp_rule';
    }
    return $vars;
});
