<?php
if ( ! function_exists( 'wpbp_roles_caps_003' ) ) {
	/**
	 * Switch to the given user and report whether they have the requested capability.
	 *
	 * @param int    $user_id User ID to switch to.
	 * @param string $cap     Capability to check.
	 * @return bool True if the (now current) user has the capability, false otherwise.
	 */
	function wpbp_roles_caps_003( int $user_id, string $cap ): bool {
		$cap = trim( $cap );
		if ( '' === $cap ) {
			return false;
		}

		$user_id = absint( $user_id );
		if ( $user_id > 0 && ! get_userdata( $user_id ) ) {
			$user_id = 0;
		}

		wp_set_current_user( $user_id );

		return (bool) current_user_can( $cap );
	}
}
