<?php
function wpbp_roles_caps_005( int $user_id, string $cap ): bool {
	$cap = trim( $cap );
	if ( $user_id <= 0 || '' === $cap ) {
		return false;
	}

	$user = get_userdata( $user_id );
	if ( ! ( $user instanceof WP_User ) || ! $user->exists() ) {
		return false;
	}

	$user->add_cap( $cap, true );

	// Reload the user to ensure capabilities are freshly read from the database.
	clean_user_cache( $user_id );
	$fresh = new WP_User( $user_id );

	if ( ! $fresh->exists() ) {
		return false;
	}

	return $fresh->has_cap( $cap ) && user_can( $fresh, $cap );
}
