<?php
/**
 * Returns the primitive capabilities WordPress requires for the given user
 * to delete the given post, as resolved by WordPress meta-capability mapping.
 *
 * @param int $user_id User ID.
 * @param int $post_id Post ID.
 * @return string[] List of primitive capabilities.
 */
function wpbp_roles_caps_008( int $user_id, int $post_id ): array {
	if ( ! function_exists( 'map_meta_cap' ) ) {
		require_once ABSPATH . WPINC . '/capabilities.php';
	}

	$caps = map_meta_cap( 'delete_post', $user_id, $post_id );

	if ( ! is_array( $caps ) ) {
		return array( 'do_not_allow' );
	}

	$caps = array_filter(
		array_map( 'strval', $caps ),
		static function ( $cap ) {
			return '' !== $cap;
		}
	);

	return array_values( array_unique( $caps ) );
}
