<?php
/**
 * Registers and enqueues the 'wpbp-inline' script handle and attaches
 * inline JavaScript after it.
 *
 * @return void
 */
function wpbp_scripts_styles_002(): void {
	$handle = 'wpbp-inline';

	if ( ! wp_script_is( $handle, 'registered' ) ) {
		wp_register_script( $handle, false, array(), null, true );
	}

	wp_enqueue_script( $handle );

	wp_add_inline_script( $handle, 'window.wpbpInline = true;', 'after' );
}
