	if (
		'' !== $url
		&& ! preg_match( '/^[a-z][a-z0-9+.-]*:/i', $url )
		&& '/' !== $url[0]
		&& '#' !== $url[0]
		&& '?' !== $url[0]
	) {
		$url = ( 0 === strpos( $url, '//' ) ? 'https:' : 'https://' ) . $url;
	}

	return esc_url( $url, array( 'http', 'https' ), 'display' );
}
